# --------------------------------------------------------------------------
# Consult max-semantics (process window vs fleet window)
# --------------------------------------------------------------------------


def test_consult_max_f1_j0p0_v0p05():
    damper, window, clock, wall = adopt_clocks('batch_pipeline_dev', jitter=0, now=10.0)
    client = StormDocsClient()
    for _ in range(1):
        damper.arm('batch_merge', client=None)  # the 1-th exhaustion: process window only
    window.publish('batch_merge', 0.05, client=client)
    waited, generation = damper.consult('batch_merge', client=client)
    assert waited == pytest.approx(0.125)  # the process window wins
    assert clock.sleeps == [pytest.approx(0.125)]
    assert generation == 1


