# --------------------------------------------------------------------------
# retry_after parity with the broadcast payload
# --------------------------------------------------------------------------


def test_retry_after_parity_f1_j0p0(monkeypatch):
    silence_chain_sleep(monkeypatch)
    damper, window, clock, wall = adopt_clocks('batch_pipeline_dev', jitter=0, now=10.0)
    client = StormDocsClient(abort_times=10**6)
    store = default_store(monkeypatch, client=client)
    error = exhaust_run(store, 'batch_merge_commit', times=1)
    assert error.retry_after == pytest.approx(0.125)
    payload = client.set_calls[-1][2]
    assert payload['window_seconds'] == pytest.approx(0.125)
    assert payload['armed_until'] == pytest.approx(1_000_000.0 + 0.125)


