# --------------------------------------------------------------------------
# Full chain schedule with an entry adopt
# --------------------------------------------------------------------------


def test_chain_schedule_aborts1_j0p0_v0p125(monkeypatch):
    silence_chain_sleep(monkeypatch)
    damper, window, clock, wall = adopt_clocks('batch_pipeline_dev', jitter=0.0, now=10.0)
    client = StormDocsClient(abort_times=1)
    window.publish('batch_merge_commit', 0.125, client=client)
    writes_before = len(client.set_calls)
    store = default_store(monkeypatch, client=client)
    assert store.run(lambda tx: 'ok', operation='batch_merge_commit') == 'ok'
    # The entry adopt heads the schedule; the rung waits ([0.1]) are the chain's own.
    assert clock.sleeps == [pytest.approx(0.125)]
    assert len(client.set_calls) == writes_before  # a committed chain never broadcasts


