# --------------------------------------------------------------------------
# Sibling pod adoption of the broadcast document
# --------------------------------------------------------------------------


def test_sibling_pod_adopts_broadcast_f1_j0p0():
    damper, window, clock, wall = adopt_clocks('batch_pipeline_dev', jitter=0, now=10.0)
    first_pod = StormDocsClient()
    for _ in range(1):
        damper.arm('batch_merge', client=first_pod)
    sibling = fresh_window('batch_pipeline_dev', wall=wall)  # fresh mirror, same Firestore
    sibling_docs = StormDocsClient()
    sibling_docs.docs = dict(first_pod.docs)
    assert sibling.peek('batch_merge', client=sibling_docs) == pytest.approx(0.125)
    assert len(sibling_docs.get_calls) == 1
    assert sibling_docs.get_calls[0][:2] == ('batch_pipeline_dev_storm_dampers', 'batch_merge')
    assert len(sibling_docs.set_calls) == 0  # the adopt never writes


