# --------------------------------------------------------------------------
# Adopt, succeed, adopt again
# --------------------------------------------------------------------------


def test_adopt_succeed_readopt_v0p125_j0p0(monkeypatch):
    silence_chain_sleep(monkeypatch)
    damper, window, clock, wall = adopt_clocks('batch_pipeline_dev', jitter=0, now=10.0)
    client = StormDocsClient()
    window.publish('batch_merge_commit', 0.125, client=client)
    store = default_store(monkeypatch, client=StormDocsClient())
    store.run(lambda tx: 'ok', operation='batch_merge_commit')
    assert clock.sleeps == [pytest.approx(0.125)]
    assert damper._generations == {}  # success cleared the process ladder
    wall.advance(0.01)
    store.run(lambda tx: 'ok', operation='batch_merge_commit')
    assert clock.sleeps[-1] == pytest.approx(0.125 - 0.01)  # the fleet window still damps


