# --------------------------------------------------------------------------
# Local expired, fleet live
# --------------------------------------------------------------------------


def test_local_expired_fleet_live_f1_v1p0():
    damper, window, clock, wall = adopt_clocks('batch_pipeline_dev', jitter=0.0, now=10.0)
    client = StormDocsClient()
    damper.arm('batch_merge', client=None)
    window.publish('batch_merge', 1.0, client=client)
    clock.now += 0.125 + 0.5  # the process window expired
    waited, generation = damper.consult('batch_merge', client=client)
    assert waited == pytest.approx(1.0)  # only the fleet window remains
    assert clock.sleeps == [pytest.approx(1.0)]
    assert generation == 1


